import{_ as n,H as a,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"09 | 进阶：会话Session与Fork分叉管理探索不同投资逻辑","description":"","frontmatter":{},"headers":[{"level":2,"title":"ClaudeSDKClient 早已把会话存好","slug":"claudesdkclient-早已把会话存好","link":"#claudesdkclient-早已把会话存好","children":[]},{"level":2,"title":"改造 agent.py：从一次性改为可接力、可分叉","slug":"改造-agent-py-从一次性改为可接力、可分叉","link":"#改造-agent-py-从一次性改为可接力、可分叉","children":[{"level":3,"title":"在 ClaudeSDKClient 中取出 session_id","slug":"在-claudesdkclient-中取出-session-id","link":"#在-claudesdkclient-中取出-session-id","children":[]},{"level":3,"title":"Resume 的实现","slug":"resume-的实现","link":"#resume-的实现","children":[]},{"level":3,"title":"Fork 探索不同投资逻辑","slug":"fork-探索不同投资逻辑","link":"#fork-探索不同投资逻辑","children":[]},{"level":3,"title":"CLI 入口：让命令行直接选择模式","slug":"cli-入口-让命令行直接选择模式","link":"#cli-入口-让命令行直接选择模式","children":[]}]},{"level":2,"title":"测试效果","slug":"测试效果","link":"#测试效果","children":[{"level":3,"title":"先跑一份“基准研报”","slug":"先跑一份-基准研报","link":"#先跑一份-基准研报","children":[]},{"level":3,"title":"下周继续——Resume 模式","slug":"下周继续——resume-模式","link":"#下周继续——resume-模式","children":[]},{"level":3,"title":"探索不同投资逻辑——Fork 模式","slug":"探索不同投资逻辑——fork-模式","link":"#探索不同投资逻辑——fork-模式","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"HarnessAgent脚手架实战课/09｜进阶：会话Session与Fork分叉管理探索不同投资逻辑.md","filePath":"HarnessAgent脚手架实战课/09｜进阶：会话Session与Fork分叉管理探索不同投资逻辑.md","lastUpdated":1795487647000}'),i={name:"HarnessAgent脚手架实战课/09｜进阶：会话Session与Fork分叉管理探索不同投资逻辑.md"};function t(l,s,o,r,u,c){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_09-进阶-会话session与fork分叉管理探索不同投资逻辑" tabindex="-1">09 | 进阶：会话Session与Fork分叉管理探索不同投资逻辑 <a class="header-anchor" href="#_09-进阶-会话session与fork分叉管理探索不同投资逻辑" aria-label="Permalink to &quot;09 | 进阶：会话Session与Fork分叉管理探索不同投资逻辑&quot;">​</a></h1><p>你好，我是邢云阳。</p><p>上一节课我们用 SubAgent 把燕京啤酒的“行业 + 财报 + 风险”三路分析跑了一遍，感受到了多Agent 协同的威力。</p><p>但其实如果是一个专业人士实际用起来，会发现还有很多可以优化的地方，例如：每一次与Agent 的对话都是一次全新的开始，没有任何历史记录或者上下文可以参考。这样一方面造成token 浪费，另一方面，上次跑的过程中得到的一些有价值的分析结论、风险等等，也全部归零了。</p><p>此外，金融分析师常常会有探索不同投资逻辑的需求。比如对于同一份年报，在基础分析的基础上，还想分别用 DCF 估值、相对估值等跑一遍，或者验证一下 PB-ROE 回归的有效性，几条支线互相不影响，结果都需要保留。</p><p>这些场景与模型的特性是天然互斥的，因为模型是无状态的——它的中间推理、它调过的Skills、它走过的工具调用，重来一遍就全没了。所以，我们只能靠一些外部工程化手段去解决问题。幸运的是，Claude Agent SDK 已经把这件事解决了。这一节，我们就来打通resume 与 fork 这两条关键能力。</p><h2 id="claudesdkclient-早已把会话存好" tabindex="-1">ClaudeSDKClient 早已把会话存好 <a class="header-anchor" href="#claudesdkclient-早已把会话存好" aria-label="Permalink to &quot;ClaudeSDKClient 早已把会话存好&quot;">​</a></h2><p>我们之前在金融研报项目中一直用的是 ClaudeSDKClient，而不是用 query() 这个简洁但对话是一次性的函数式 API。是因为 ClaudeSDKClient 的可玩性更高，它为我们开放了更多可以控制的能力。</p><p>比如 Claude Agent SDK 会自动把会话历史落盘到 ~/.claude/projects//*.jsonl。我们使用ClaudeSDKClient，便可以继续拿到这些历史对话。</p><p>那拿到这些历史对话做什么用呢？官方帮我们规划好了两种用途，这是官方文档中的核心对比。</p><p>使用方式</p><ul><li>适合场景</li></ul><p>client.query(...,</p><ul><li>进程重启后精确恢复任意历史会话</li></ul><p>options=ClaudeAgentOptions(resume=sid))</p><p>client.query(...,options=ClaudeAgentOptions(resume=sid,</p><ul><li>恢复历史会话，并派生分支，原会话不</li></ul><p>fork_session=True))</p><p>读到这里，是不是大概能猜到投研场景会怎么用两种方式了？</p><ul><li><p>首先跑一次新分析，拿到 session_id 存好；</p></li><li><p>如果下周接着聊，用 resume；</p></li><li><p>如果想换个估值方法，用 fork，此时可以比较 DCF / 相对估值，并且两套结果各自保留，互不污染。</p></li></ul><p>想到饿了就开始行动吧，我们这就把上节课实现的 agent.py 改造成支持这两种用法。</p><h2 id="改造-agent-py-从一次性改为可接力、可分叉" tabindex="-1">改造 agent.py：从一次性改为可接力、可分叉 <a class="header-anchor" href="#改造-agent-py-从一次性改为可接力、可分叉" aria-label="Permalink to &quot;改造 agent.py：从一次性改为可接力、可分叉&quot;">​</a></h2><p>代码入口与三个 SubAgent 的定义的代码保持不变。</p><h3 id="在-claudesdkclient-中取出-session-id" tabindex="-1">在 ClaudeSDKClient 中取出 session_id <a class="header-anchor" href="#在-claudesdkclient-中取出-session-id" aria-label="Permalink to &quot;在 ClaudeSDKClient 中取出 session_id&quot;">​</a></h3><p>首先 ClaudeSDKClient 会在内部保留会话状态，多次 client.query() 会被自动串成同一段对话。我们需要把 session_id 拿出来，方便后续使用，代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def run_fresh(prompt: str) -&gt; str:</span></span>
<span class="line"><span>   options = ClaudeAgentOptions(</span></span>
<span class="line"><span>       system_prompt=SYSTEM_PROMPT,</span></span>
<span class="line"><span>       include_partial_messages=True,</span></span>
<span class="line"><span>       mcp_servers={&quot;websearch&quot;: websearch_server},</span></span>
<span class="line"><span>       allowed_tools=[</span></span>
<span class="line"><span>           &quot;Read&quot;, &quot;Grep&quot;, &quot;Glob&quot;, &quot;Agent&quot;, &quot;AskUserQuestion&quot;,</span></span>
<span class="line"><span>           &quot;mcp__websearch__bochasearch&quot;,</span></span>
<span class="line"><span>       ],</span></span>
<span class="line"><span>       agents=build_agents(),</span></span>
<span class="line"><span>   )</span></span>
<span class="line"><span>   session_id = None</span></span>
<span class="line"><span>   async with ClaudeSDKClient(options=options) as client:</span></span>
<span class="line"><span>       await client.query(prompt)</span></span>
<span class="line"><span>       async for msg in client.receive_response():</span></span>
<span class="line"><span>           print(msg)                                    # 与 08 课一致</span></span>
<span class="line"><span>           if isinstance(msg, ResultMessage):</span></span>
<span class="line"><span>               session_id = msg.session_id              # ★ 关键一行</span></span>
<span class="line"><span>   return session_id</span></span></code></pre></div><p>划重点：在 Python SDK 里，session_id 是 ResultMessage 的一个字段。我们一边消费消息一边把它捞出来——这是后续 resume / fork 的入口。</p><p>下面我们具体来实现 resume 和 fork 两种功能。</p><h3 id="resume-的实现" tabindex="-1">Resume 的实现 <a class="header-anchor" href="#resume-的实现" aria-label="Permalink to &quot;Resume 的实现&quot;">​</a></h3><p>可以使用 resume 参数来实现从历史对话中恢复提问。代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def run_resume(session_id: str, follow_up: str) -&gt; None:</span></span>
<span class="line"><span>   &quot;&quot;&quot;模式一：基于上次的研报，继续追问。&quot;&quot;&quot;</span></span>
<span class="line"><span>   options = ClaudeAgentOptions(</span></span>
<span class="line"><span>       resume=session_id,                               # ★ 关键：恢复历史</span></span>
<span class="line"><span>       allowed_tools=[</span></span>
<span class="line"><span>           &quot;Read&quot;, &quot;Grep&quot;, &quot;Glob&quot;, &quot;Agent&quot;, &quot;AskUserQuestion&quot;,</span></span>
<span class="line"><span>           &quot;mcp__websearch__bochasearch&quot;,</span></span>
<span class="line"><span>       ],</span></span>
<span class="line"><span>   )</span></span>
<span class="line"><span>   async with ClaudeSDKClient(options=options) as client:</span></span>
<span class="line"><span>       await client.query(follow_up)</span></span>
<span class="line"><span>       async for msg in client.receive_response():</span></span>
<span class="line"><span>           print(msg)</span></span></code></pre></div><p>注意几个细节：</p><ul><li><p>resume 是从历史会话 ID 中恢复——这意味着即使你关掉进程、关掉电脑，下次再resume，SubAgent 也记得它上一轮说过什么、读过哪些 PDF。</p></li><li><p>这里我们没有重新传 system_prompt 等等，是因为历史会话里已经记录了。</p></li></ul><h3 id="fork-探索不同投资逻辑" tabindex="-1">Fork 探索不同投资逻辑 <a class="header-anchor" href="#fork-探索不同投资逻辑" aria-label="Permalink to &quot;Fork 探索不同投资逻辑&quot;">​</a></h3><p>投研最常见的用法。DCF 跑一份、相对估值跑一份，两者互不污染，实现代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def run_fork(session_id: str, alternative: str) -&gt; str:</span></span>
<span class="line"><span>   &quot;&quot;&quot;模式二：基于原会话派生分支，原研报保留不动。&quot;&quot;&quot;</span></span>
<span class="line"><span>   options = ClaudeAgentOptions(</span></span>
<span class="line"><span>       resume=session_id,</span></span>
<span class="line"><span>       fork_session=True,                               # ★ 关键：派生分支</span></span>
<span class="line"><span>       max_turns=5,</span></span>
<span class="line"><span>   )</span></span>
<span class="line"><span>   forked_id = None</span></span>
<span class="line"><span>   async with ClaudeSDKClient(options=options) as client:</span></span>
<span class="line"><span>       await client.query(alternative)</span></span>
<span class="line"><span>       async for msg in client.receive_response():</span></span>
<span class="line"><span>           print(msg)</span></span>
<span class="line"><span>           if isinstance(msg, ResultMessage):</span></span>
<span class="line"><span>               forked_id = msg.session_id               # 分支自己的 id</span></span>
<span class="line"><span>return forked id</span></span></code></pre></div><p>fork_session=True 会把当前历史完整复制一份给新分支，新分支的修改不会回写原会话。所以你可以放心地让 SubAgent 在分支里尝试 DCF、在原会话里继续追问“2026Q1 业绩展望”，这两条线互不打架。</p><h3 id="cli-入口-让命令行直接选择模式" tabindex="-1">CLI 入口：让命令行直接选择模式 <a class="header-anchor" href="#cli-入口-让命令行直接选择模式" aria-label="Permalink to &quot;CLI 入口：让命令行直接选择模式&quot;">​</a></h3><p>最后，我们可以简单做一个命令行工具。这个工具能让我们在启动 Agent 时，可以选择是恢复历史对话还是派生分支，代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>async def main():</span></span>
<span class="line"><span>   parser = argparse.ArgumentParser()</span></span>
<span class="line"><span>   parser.add_argument(&quot;--resume&quot;, help=&quot;从已有 session_id 继续追问&quot;)</span></span>
<span class="line"><span>   parser.add_argument(&quot;--fork&quot;,   help=&quot;基于已有 session_id 派生分支&quot;)</span></span>
<span class="line"><span>   parser.add_argument(&quot;prompt&quot;, nargs=&quot;?&quot;, default=DEFAULT_PROMPT)</span></span>
<span class="line"><span>   args = parser.parse_args()</span></span>
<span class="line"><span>   if args.fork:</span></span>
<span class="line"><span>       forked = await run_fork(args.resume or args.prompt, args.prompt)</span></span>
<span class="line"><span>       print(f&quot;\\n[FORK_SESSION_ID] {forked}&quot;)</span></span>
<span class="line"><span>   elif args.resume:</span></span>
<span class="line"><span>       await run_resume(args.resume, args.prompt)</span></span>
<span class="line"><span>   else:</span></span>
<span class="line"><span>       sid = await run_fresh(args.prompt)</span></span>
<span class="line"><span>       print(f&quot;\\n[SESSION_ID] {sid}&quot;)</span></span>
<span class="line"><span>       print(&quot;# 之后用：&quot;)</span></span>
<span class="line"><span>       print(f&quot;# python researcher.py --resume {sid} \\&quot;请补充最新一周行业利空\\&quot;&quot;)</span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>   asyncio.run(main())</span></span></code></pre></div><p>注意 args.fork 分支里，我们允许两种入口：</p><ul><li><p>python researcher.py --fork&quot;换成 DCF 估值&quot;：显式传 sid；</p></li><li><p>python researcher.py --fork &quot;换成 DCF 估值&quot;：省略 sid 时，从最近一次运行的缓存里读（这是我们后面可以加的小优化，本节先留口子）。</p></li></ul><h2 id="测试效果" tabindex="-1">测试效果 <a class="header-anchor" href="#测试效果" aria-label="Permalink to &quot;测试效果&quot;">​</a></h2><p>完成代码改造后，我们不妨做几个实验来测试一下效果。</p><h3 id="先跑一份-基准研报" tabindex="-1">先跑一份“基准研报” <a class="header-anchor" href="#先跑一份-基准研报" aria-label="Permalink to &quot;先跑一份“基准研报”&quot;">​</a></h3><p>首先，我们不使用任何命令参数，跑一份基准的对话过程。此时控制台会输出 SubAgent 的中间推理、Skills 调用过程，与上一节完全一致。唯一的差别是最后多了几行打印。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/1.png" alt=""></a></p><p>把 session_id 当作你的研报。它不是一次性的 shell 输出，而是你这一周投研工作的存档。</p><h3 id="下周继续——resume-模式" tabindex="-1">下周继续——Resume 模式 <a class="header-anchor" href="#下周继续——resume-模式" aria-label="Permalink to &quot;下周继续——Resume 模式&quot;">​</a></h3><p>假设你跑完基准研报后，又看到一条新闻：“2026 年上半年，啤酒行业销量成整体下滑趋势，7 月随为夏季传统啤酒销售季，但受宏观经济、消费场景疲软等影响，整体销量同比仍面临一定的下行压力”。</p><p>于是，你想让主 Agent 拉上行业 + 风险两个 SubAgent，再做一次增量分析，但不要重跑财报。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python agent.py --resume 1f132a87-b9d9-4777-9b64-4a7ceef0adcd &quot;消息：2026 年上半年</span></span></code></pre></div><p>测试结果如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/2.png" alt=""></a></p><p>注意此时发生了什么：</p><ul><li><p>SubAgent 不会重新读 PDF、不会重新调 financial-report-analyzer——这些中间产物已经在历史里；</p></li><li><p>主 Agent 把“这次的新问题”接到了上次的分析结论上；</p></li><li><p>你拿到的是增量更新，不是全量重跑。</p></li></ul><p>所以，Resume 的功能还是非常强大和有用的，其能保证历史对话不丢，而且还能实现“断点续传”。</p><h3 id="探索不同投资逻辑——fork-模式" tabindex="-1">探索不同投资逻辑——Fork 模式 <a class="header-anchor" href="#探索不同投资逻辑——fork-模式" aria-label="Permalink to &quot;探索不同投资逻辑——Fork 模式&quot;">​</a></h3><p>DCF 估值 vs 相对估值，这是两类完全不同的投资逻辑。Fork 让我们可以同时探索它们：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 分支一：用 DCF 重做估值（默认行为：完全沿用上周的风险与行业分析）</span></span>
<span class="line"><span>$ python agent.py --fork 1f132a87-b9d9-4777-9b64-4a7ceef0adcd \\</span></span>
<span class="line"><span>   &quot;请基于现有分析，额外用 DCF 模型重做估值，重点关注 WACC 假设&quot;</span></span>
<span class="line"><span># 分支二：用相对估值法（PE/PB 历史分位）</span></span>
<span class="line"><span>$ python agent.py --fork 1f132a87-b9d9-4777-9b64-4a7ceef0adcd \\</span></span>
<span class="line"><span>   &quot;请基于现有分析，额外用 PE/PB 历史分位法做估值，给出 25%/50%/75% 三个情景&quot;</span></span></code></pre></div><p>测试结果如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/3.png" alt=""></a></p><ul><li>分支一</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/HarnessAgent%E8%84%9A%E6%89%8B%E6%9E%B6%E5%AE%9E%E6%88%98%E8%AF%BE/images/09/4.png" alt=""></a></p><ul><li>分支二</li></ul><p>两条分支跑下来后，原始研报完全没动。你可以同时比较：</p><ul><li><p>哪种估值方法对燕京啤酒这种成熟消费品更合适？</p></li><li><p>两种方法给出的买卖价位差多少？</p></li><li><p>风险因子在两种估值下是否一致？</p></li></ul><p>Fork 让我们可以在多条投资思路上进行并行探索，互不污染上下文，互不污染结果。</p><p>而且你还能在分支里继续追问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ python agent.py --resume &lt;分支id&gt; &quot;在 DCF 估值基础上，把永续增长率调到 1% 重新算一下&quot;</span></span></code></pre></div><p>会话是链式的，分支之上还能再分，SubAgent 的工作记忆被完整保留。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课，我们实践了 Claude Agent SDK 中两个代码极其简单、但功能却非常强大的特性。这两个特性，一个可以解决接着历史对话继续聊天的问题，另一个则可以解决沿着历史对话分多条支线，分别进行聊天探索的问题。</p><p>想象一下，在过去几年，如果要让我们自己来实现这两个功能，光是历史对话存取，可能就得上一些向量库，数据库等手段。但如今，Claude Agent SDK 用一个文件存取的方式就解决了存储问题，之后又把两个功能的代码做了很好的封装，使得我们只需要拿着 session_id 去配一下参数就可以用了。</p><p>让 AI 开发回归业务本身，将是大势所趋。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>请结合你自己的工作场景思考这样几个问题。</p><ul><li><p>你的 Agent 任务里，哪类工作天然需要 Resume？（例如：跨日跟进、阶段性复盘）</p></li><li><p>哪类工作天然适合 Fork？（例如：多策略并行、多数据源对比）</p></li><li><p>如果把 Session / Fork 思路推广到团队里，多人协作会因此发生怎样的变化？</p></li></ul><p>期待看到你在留言区展示思考过程，我们一起探讨。如果你觉得这节课的内容对你有帮助的话，也欢迎你分享给其他朋友，我们下节课再见！</p>`,79)])])}const g=n(i,[["render",t]]);export{h as __pageData,g as default};
